[{"order":1,"type":"heading","text":"SOLID Principles in JavaScript"},{"order":2,"type":"paragraph","text":"SOLID is an acronym for five design principles intended to make software designs more understandable, flexible, and maintainable. Applying these principles in JavaScript can lead to cleaner, more robust code."},{"order":3,"type":"subheading","text":"1. Single Responsibility Principle (SRP)"},{"order":4,"type":"paragraph","text":"A class should have only one reason to change. In other words, a class should have only one job. This principle promotes high cohesion and low coupling."},{"order":5,"type":"code","text":"// Bad example: A class with multiple responsibilities
class User {
  constructor(name, email) {
    this.name = name;
    this.email = email;
  }

  save() {
    // Save user to database
    console.log('Saving user to database');
  }

  sendEmail(message) {
    // Send email to user
    console.log('Sending email: ' + message);
  }
}

// Good example: Separating responsibilities
class User {
  constructor(name, email) {
    this.name = name;
    this.email = email;
  }
}

class UserRepository {
  save(user) {
    // Save user to database
    console.log('Saving user to database');
  }
}

class UserMailer {
  sendEmail(user, message) {
    // Send email to user
    console.log('Sending email to ' + user.email + ': ' + message);
  }
}"},{"order":6,"type":"subheading","text":"2. Open/Closed Principle (OCP)"},{"order":7,"type":"paragraph","text":"Software entities (classes, modules, functions, etc.) should be open for extension, but closed for modification. This means you should be able to add new functionality without changing existing code."},{"order":8,"type":"code","text":"// Bad example: Modifying existing code to add new functionality
class AreaCalculator {
  constructor(shapes) {
    this.shapes = shapes;
  }

  sum() {
    let area = 0;
    for (const shape of this.shapes) {
      if (shape instanceof Rectangle) {
        area += shape.width * shape.height;
      } else if (shape instanceof Circle) {
        area += Math.PI * shape.radius * shape.radius;
      }
    }
    return area;
  }
}

// Good example: Using inheritance and interfaces for extension
class Shape {
  area() {
    throw new Error('Area method must be implemented');
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super();
    this.width = width;
    this.height = height;
  }

  area() {
    return this.width * this.height;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super();
    this.radius = radius;
  }

  area() {
    return Math.PI * this.radius * this.radius;
  }
}

class AreaCalculator {
  constructor(shapes) {
    this.shapes = shapes;
  }

  sum() {
    let area = 0;
    for (const shape of this.shapes) {
      area += shape.area();
    }
    return area;
  }
}"},{"order":9,"type":"subheading","text":"3. Liskov Substitution Principle (LSP)"},{"order":10,"type":"paragraph","text":"Subtypes must be substitutable for their base types without altering the correctness of the program. If a subclass is used where its base class is expected, the program should still behave correctly."},{"order":11,"type":"code","text":"// Bad example: Violating LSP
class Rectangle {
  constructor(width, height) {
    this.width = width;
    this.height = height;
  }

  setWidth(width) {
    this.width = width;
  }

  setHeight(height) {
    this.height = height;
  }

  area() {
    return this.width * this.height;
  }
}

class Square extends Rectangle {
  setWidth(width) {
    this.width = width;
    this.height = width;
  }

  setHeight(height) {
    this.width = height;
    this.height = height;
  }
}

function increaseRectangleWidth(rectangle) {
  const oldWidth = rectangle.width;
  rectangle.setWidth(rectangle.width + 10);
  const expectedArea = rectangle.height * (oldWidth + 10);
  if (rectangle.area() !== expectedArea) {
    throw new Error('LSP violation');
  }
}

// Good example: Adhering to LSP
class Shape {
  area() {
    throw new Error('Area method must be implemented');
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super();
    this.width = width;
    this.height = height;
  }

  area() {
    return this.width * this.height;
  }
}

class Square extends Shape {
  constructor(side) {
    super();
    this.side = side;
  }

  area() {
    return this.side * this.side;
  }
}"},{"order":12,"type":"subheading","text":"4. Interface Segregation Principle (ISP)"},{"order":13,"type":"paragraph","text":"Clients should not be forced to depend on methods they do not use. Instead of one large interface, many small, client-specific interfaces are preferred."},{"order":14,"type":"code","text":"// Bad example: Fat interface
class Machine {
  print() {
    throw new Error('Not implemented');
  }

  scan() {
    throw new Error('Not implemented');
  }

  fax() {
    throw new Error('Not implemented');
  }
}

class OldFashionedPrinter extends Machine {
  print() {
    //...
  }

  scan() {
    throw new Error('Not supported');
  }

  fax() {
    throw new Error('Not supported');
  }
}

// Good example: Segregated interfaces
class Printer {
  print() {
    throw new Error('Not implemented');
  }
}

class Scanner {
  scan() {
    throw new Error('Not implemented');
  }
}

class Fax {
  fax() {
    throw new Error('Not implemented');
  }
}

class JustAPrinter extends Printer {
  print() {
    //...
  }
}

class MultiFunctionPrinter extends Printer {
  print() {
    //...
  }
  scan(){
    //...
  }
}"},{"order":15,"type":"subheading","text":"5. Dependency Inversion Principle (DIP)"},{"order":16,"type":"paragraph","text":"High-level modules should not depend on low-level modules. Both should depend on abstractions. Abstractions should not depend on details. Details should depend on abstractions. This principle promotes loose coupling."},{"order":17,"type":"code","text":"// Bad example: High-level module depending on low-level module
class LightBulb {
  turnOn() {
    console.log('LightBulb: Bulb turned on...');
  }

  turnOff() {
    console.log('LightBulb: Bulb turned off...');
  }
}

class Switch {
  constructor(bulb) {
    this.bulb = bulb;
  }

  on() {
    this.bulb.turnOn();
  }

  off() {
    this.bulb.turnOff();
  }
}

// Good example: Depending on abstraction
class Switchable {
  on() {
    throw new Error('Not implemented');
  }

  off() {
    throw new Error('Not implemented');
  }
}

class LightBulb extends Switchable {
  on() {
    console.log('LightBulb: Bulb turned on...');
  }

  off() {
    console.log('LightBulb: Bulb turned off...');
  }
}

class Switch {
  constructor(device) {
    this.device = device;
  }

  on() {
    this.device.on();
  }

  off() {
    this.device.off();
  }
}"},{"order":18,"type":"paragraph","text":"By applying the SOLID principles, you can create more maintainable, flexible, and robust JavaScript applications. Remember that these are guidelines, not strict rules, and should be applied judiciously based on the specific context of your project."}]
